function asciiBytes(s){const o=[];for(let i=0;i<s.length;i++)o.push(s.charCodeAt(i)&255);return o;}
function hexToBytes(hex){const o=[];for(let i=0;i<hex.length;i+=2)o.push(parseInt(hex.substr(i,2),16));return o;}
function hmacHex(key,msg){const block=64;let k=asciiBytes(key);if(k.length>block)k=hexToBytes(sha256Bytes(k));while(k.length<block)k.push(0);const oKey=k.map(b=>b^0x5c);const iKey=k.map(b=>b^0x36);const inner=sha256Bytes(iKey.concat(asciiBytes(msg)));return sha256Bytes(oKey.concat(hexToBytes(inner)));}
