const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in n8n env');

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'] || '');

let body = '';
if (typeof item.json.rawBody === 'string') body = item.json.rawBody;
else if (typeof item.json.body === 'string') body = item.json.body;
else if (item.json.body && typeof item.json.body === 'object') body = JSON.stringify(item.json.body);
else body = JSON.stringify(item.json);

if (!timestamp || !signature) throw new Error('Missing signature headers');
const skew = Math.abs(Date.now() - Number(timestamp));
if (!Number.isFinite(Number(timestamp)) || skew > 5 * 60 * 1000) throw new Error('Timestamp skew too large');

const expected = hmacHex(secret, `${timestamp}.${body}`);
if (!safeEqual(expected, signature)) throw new Error('Invalid HMAC signature');

const payload = JSON.parse(body);
return [{
  json: {
    event: payload.event,
    loanId: payload.loanId,
    toolName: payload.toolName,
    status: payload.status,
    startDate: payload.startDate,
    endDate: payload.endDate,
    notifyEmail: payload.notifyEmail,
    notifyName: payload.notifyName,
    role: payload.role,
  }
}];

const p = $input.first().json;
const line = `[LendLoop mock notify] To: ${p.notifyEmail} (${p.notifyName}/${p.role}) | ${p.event} | tool=${p.toolName} status=${p.status} ${p.startDate}→${p.endDate} loan=${p.loanId}`;
console.log(line);
return [{ json: { ...p, mockNotification: line, deliveredAt: new Date().toISOString() } }];
